  "tool": "finish",
  "args": {
    "note": "Completed address update to **ap-desk-h6y6@contoso.dev** and issued refund of 80. Pre-change archive exported successfully. Test email sent to new contact; confirmation and refund verified. Ticket resolved per handoff."
